    "transcript": "ナレーター：会議で、男の人が、アンケート調査の結果について話しています。男の人は、新車の開発で重視することは、何だと言っていますか。\n男：えー、まず、先日行いましたアンケート調査についてご報告いたします。我が社の自動車をご購入いただいたことのある方に、車選びのポイントについてお聞きし、年代別にまとめました。その結果、20代・30代では、外観と性能を基準にしている方が多いことがわかりました。また、40代・50代では、安心して乗れること、乗り心地がいいことを挙げる方が多く見られました。それから、60代以上では、燃費がいいことを一番に挙げる方が多いという結果が得られました。今回の新車は、高齢者層がターゲットですので、このアンケート結果を踏まえて、今回は、特にこの点に力を入れて、開発に取り組んでいくことになりました。\nナレーター：男の人は、新車の開発で重視することは、何だと言っていますか。\n① デザイン。\n② 走行性。\n③ 安全性。\n④ 経済性。",
    "transcriptWithFurigana": "ナレーター：会議(かいぎ)で、男(おとこ)の人(ひと)が、アンケート調査(ちょうさ)の結果(けっか)について話(はなし)しています。男(おとこ)の人(ひと)は、新車(しんしゃ)の開発(かいはつ)で重視(じゅうし)することは、何(なに)だと言(い)っていますか。\n男(おとこ)：えー、まず、先日(せんじつ)行(い)いましたアンケート調査(ちょうさ)についてご報告(ほうこく)いたします。我(わ)が社(しゃ)の自動車(じどうしゃ)をご購入(こうにゅう)いただいたことのある方(かた)に、車(くるま)選びのポイントについてお聞(き)きし、年代別(ねんだいべつ)にまとめました。その結果(けっか)、20代(だい)・30代(だい)では、外観(がいかん)と性能(せいのう)を基準(きじゅん)にしている方(かた)が多い(おおい)ことがわかりました。また、40代(だい)・50代(だい)では、安心(あんしん)して乗(の)れること、乗り心地(のりごこち)がいいことを挙(あ)げる方(かた)が多(おお)く見(み)られました。それから、60代(だい)以上(うえ)では、燃費(ねんぴ)がいいことを一番(いちばん)に挙(あ)げる方(かた)が多い(おおい)という結果(けっか)が得(え)られました。今回(こんかい)の新車(しんしゃ)は、高齢者層(こうれいしゃそう)がターゲットですので、このアンケート結果(けっか)を踏(ふ)まえて、今回(こんかい)は、特(とく)にこの点(てん)に力(ちから)を入(い)れて、開発(かいはつ)に取(と)り組(く)んでいくことになりました。\nナレーター：男(おとこ)の人(ひと)は、新車(しんしゃ)の開発(かいはつ)で重視(じゅうし)することは、何(なに)だと言(い)っていますか。\n① デザイン。\n② 走行性(そうこうせい)。\n③ 安全性(あんぜんせい)。\n④ 経済性(けいざいせい)。",
    "translationZhTW": "旁白：會議中，一名男子正在說明問卷調查結果。他說新車開發最重視的是什麼？\n男：首先報告前幾天進行的問卷調查。我們詢問曾購買本公司汽車的顧客選車時重視的要點，並按年齡層整理。結果顯示，20、30多歲多以外觀和性能為基準；40、50多歲則較多人重視乘坐安全與舒適；60歲以上最多人把油耗佳列為第一考量。這次新車的目標客群是高齡者，因此根據這份調查，我們決定特別加強這一點來進行開發。\n旁白：男子說新車開發最重視的是什麼？\n① 設計。\n② 行駛性能。\n③ 安全性。\n④ 經濟性（油耗）。",
