    "transcript": "ナレーター：男の人と女の人が、新しいシステムの導入について、話しています。女の人は、このシステムの導入による最大のメリットは、何だと言っていますか。\n男：そういえば、来年度から新システムを導入するんだって？\n女：はい。これまでは、週明けに売り場で商品の数を確認して、必要な数を台帳に記入して発注していましたが、新しいシステムですと、携帯用の端末に商品の数を入力するということになります。\n男：携帯端末に数を入力するだけでいいの？\n女：はい。店頭に今ある数を入力して、携帯端末のデータを送信すれば、自動的に足りない分が発注されます。\n男：これまでのように、発注書を作成して、業者にFAXしてっていうプロセスは、なくなるわけだね。\n女：ええ。現場の手間がかからなくなるというのが、一番の利点です。ほかにもメリットがあって、例えば、うちの店で商品が足りなくて、よその店で余っているような場合は、よその在庫をうちに回してもらうことなんかもできるんですよ。\n男：てことは、その逆もできるんだね。\n女：はい。\n男：そうか。じゃ、売れ残った商品を値上げして売るなんてこともしなくてもよくなるのか。\n女：はい。\nナレーター：女の人は、このシステムの導入による最大のメリットは、何だと言っていますか。\n① 商品を早く調達できること。\n② 社員の作業が少なくなること。\n③ 価格の設定が自由にできること。\n④ 在庫のロスを防げること。",
    "transcriptWithFurigana": "ナレーター：男(おとこ)の人(ひと)と女(おんな)の人(ひと)が、新(あたら)しいシステムの導入(どうにゅう)について、話(はなし)しています。女(おんな)の人(ひと)は、このシステムの導入(どうにゅう)による最大(さいだい)のメリットは、何(なに)だと言(い)っていますか。\n男(おとこ)：そういえば、来年度(らいねんど)から新(あたら)システムを導入(どうにゅう)するんだって？\n女(おんな)：はい。これまでは、週明け(しゅうあけ)に売り場(うりば)で商品(しょうひん)の数(かず)を確認(かくにん)して、必要(ひつよう)な数(かず)を台帳(だいちょう)に記入(い)して発注(はっちゅう)していましたが、新(あたら)しいシステムですと、携帯用(けいたいよう)の端末(たんまつ)に商品(しょうひん)の数(かず)を入力(にゅうりょく)するということになります。\n男(おとこ)：携帯端末(けいたいたんまつ)に数(かず)を入力(にゅうりょく)するだけでいいの？\n女(おんな)：はい。店頭(てんとう)に今(いま)ある数(かず)を入力(にゅうりょく)して、携帯端末(けいたいたんまつ)のデータを送信(そうしん)すれば、自動的(じどうてき)に足(た)りない分(ふん)が発注(はっちゅう)されます。\n男(おとこ)：これまでのように、発注書(はっちゅうしょ)を作成(さくせい)して、業者(ぎょうしゃ)にFAXしてっていうプロセスは、なくなるわけだね。\n女(おんな)：ええ。現場(げんば)の手間(てま)がかからなくなるというのが、一番(いちばん)の利点(りてん)です。ほかにもメリットがあって、例(たと)えば、うちの店(みせ)で商品(しょうひん)が足(た)りなくて、よその店(みせ)で余(あま)っているような場合(ばあい)は、よその在庫(ざいこ)をうちに回(まわ)してもらうことなんかもできるんですよ。\n男(おとこ)：てことは、その逆(ぎゃく)もできるんだね。\n女(おんな)：はい。\n男(おとこ)：そうか。じゃ、売(う)れ残(のこ)った商品(しょうひん)を値上げ(ねあげ)して売(う)るなんてこともしなくてもよくなるのか。\n女(おんな)：はい。\nナレーター：女(おんな)の人(ひと)は、このシステムの導入(どうにゅう)による最大(さいだい)のメリットは、何(なに)だと言(い)っていますか。\n① 商品(しょうひん)を早(はや)く調達(ちょうたつ)できること。\n② 社員(しゃいん)の作業(さぎょう)が少(すこ)なくなること。\n③ 価格(かかく)の設定(せってい)が自由(じゆう)にできること。\n④ 在庫(ざいこ)のロスを防(ふせ)げること。",
    "translationZhTW": "旁白：男女正在談導入新系統。女方說導入這套系統最大的優點是什麼？\n男：聽說明年度要導入新系統？\n女：是。以前週初要在賣場確認商品數量，把需要的數量寫在台帳上再下單；新系統則只要把商品數量輸入攜帶式終端。\n男：只要輸入數量就可以？\n女：是。輸入店面現有數量並傳送資料後，系統會自動訂購不足的部分。\n男：那以前製作訂購單、傳真給廠商的流程就不用了。\n女：對。最大的優點就是現場人員省事。除此之外，例如本店缺貨、其他店有剩餘時，也能把其他店的庫存調過來。\n男：反過來也可以吧。\n女：是。\n男：那就不用因為商品賣不掉而調整價格之類的了。\n女：是。\n旁白：女方說導入系統最大的優點是什麼？\n① 可以更快調貨。\n② 員工的作業量減少。\n③ 可以自由設定價格。\n④ 可以避免庫存損失。",
