    "id": "BJT_TRUE02_P1_S3_Q09",
    "transcript": "ナレーター：あるメーカーの創立記念式典で、社長が話しています。社長は今後、どんなことを目標にすると言っていますか。\n女：我が社は創業以来80年、医療機器メーカーとして、医療技術の向上に貢献してまいりました。私たちは、検査や治療の迅速化・正確性を実現するためのシステムを構築し、国民の健康の維持に寄与してまいりました。その際に医療機器が果たした役割は、きわめて大きなものでした。我が社はこれまで、医療の現場にさまざまな提案を行ってきたわけですが、当社の機器を導入してくださったお客様からは、診察や経過観察、検査において正確なデータが迅速にとれたという声が、多数寄せられるようになりました。これからもお客様のニーズに応え、さらに精度が高く、安全で正確な商品作りを目指します。\nナレーター：社長は今後、どんなことを目標にすると言っていますか。\n① 医療技術を向上させること。\n② 国民の健康維持に寄与すること。\n③ 医療機関に機器を導入させること。\n④ 信頼性の高い医療機器を作ること。",
    "transcriptWithFurigana": "ナレーター：あるメーカーの創立記念式典(そうりつきねんしきてん)で、社長(しゃちょう)が話(はなし)しています。社長(しゃちょう)は今後(こんご)、どんなことを目標(もくひょう)にすると言(い)っていますか。\n女(おんな)：我(わ)が社(しゃ)は創業以来(そうぎょういらい)80年(ねん)、医療機器(いりょうきき)メーカーとして、医療技術(いりょうぎじゅつ)の向上(こうじょう)に貢献(こうけん)してまいりました。私(わたし)たちは、検査(けんさ)や治療(ちりょう)の迅速化(じんそくか)・正確性(せいかくせい)を実現(じつげん)するためのシステムを構築(こうちく)し、国民(こくみん)の健康(けんこう)の維持(いじ)に寄与(きよ)してまいりました。その際(さい)に医療機器(いりょうきき)が果(は)たした役割(やくわり)は、きわめて大きなものでした。我(わ)が社(しゃ)はこれまで、医療(いりょう)の現場(げんば)にさまざまな提案(ていあん)を行(い)ってきたわけですが、当社(とうしゃ)の機器(きき)を導入(どうにゅう)してくださったお客様(きゃくさま)からは、診察(しんさつ)や経過観察(けいかかんさつ)、検査(けんさ)において正確(せいかく)なデータが迅速(じんそく)にとれたという声(こえ)が、多数寄(たすうよ)せられるようになりました。これからもお客様(きゃくさま)のニーズに応(こた)え、さらに精度(せいど)が高(たか)く、安全(あんぜん)で正確(せいかく)な商品(しょうひん)作(つく)りを目指(めざ)します。\nナレーター：社長(しゃちょう)は今後(こんご)、どんなことを目標(もくひょう)にすると言(い)っていますか。\n① 医療技術(いりょうぎじゅつ)を向上(こうじょう)させること。\n② 国民(こくみん)の健康(けんこう)維持(いじ)に寄与(きよ)すること。\n③ 医療機関(いりょうきかん)に機器(きき)を導入(どうにゅう)させること。\n④ 信頼性(しんらいせい)の高(たか)い医療機器(いりょうきき)を作(つく)ること。",
    "translationZhTW": "旁白：某製造商的創立紀念典禮上，社長正在致詞。她說今後的目標是什麼？\n女：本公司創業80年來，作為醫療器材製造商，一直致力於提升醫療技術。我們建立能提升檢查與治療速度、準確性的系統，並為國民健康維護做出貢獻。在其中，醫療器材扮演了極大的角色。至今我們向醫療現場提出各種方案，使用本公司器材的客戶也陸續反映，在診察、追蹤觀察與檢查時能迅速取得正確資料。今後我們仍會回應顧客需求，以製造精度更高、更安全、更準確的產品為目標。\n旁白：社長說今後的目標是什麼？\n① 提升醫療技術。\n② 為國民健康維護做出貢獻。\n③ 讓醫療機構導入器材。\n④ 製造可信賴度高的醫療器材。",
