    "id": "BJT_TRUE02_P2_S3_Q01",
    "transcript": "ナレーター：新入社員が先輩に、海外関連のファイルについて尋ねています。新入社員は、どのファイルを見ますか。\n男：先輩、アメリカのABCカンパニーとの取り引きについて資料を見たいんですが、この海外関係の棚の、どのファイルを見ればいいでしょうか？\n女：それなら輸出実績か、海外取引顧客リストを見ればわかるんじゃない？ああ、でも、具体的には何を調べたいの？\n男：最近の円高でABCカンパニーへの出荷数がどれくらい落ち込んでいるのか調べるようにって、課長に言われましたので。\n女：あー、それなら、北米支店の報告を見たほうが早いわね。\n男：はい、わかりました。ありがとうございます。\nナレーター：新入社員は、どのファイルを見ますか。",
    "transcriptWithFurigana": "ナレーター：新入社員(しんにゅうしゃいん)が先輩(せんぱい)に、海外関連(かいがいかんれん)のファイルについて尋(たず)ねています。新入社員(しんにゅうしゃいん)は、どのファイルを見(み)ますか。\n男(おとこ)：先輩(せんぱい)、アメリカのABCカンパニーとの取(と)り引(ひ)きについて資料(しりょう)を見(み)たいんですが、この海外関係(かいがいかんけい)の棚(たな)の、どのファイルを見(み)ればいいでしょうか？\n女(おんな)：それなら輸出実績(ゆしゅつじっせき)か、海外取引顧客(かいがいとりひきこきゃく)リストを見(み)ればわかるんじゃない？ああ、でも、具体的(ぐたいてき)には何(なに)を調(しら)べたいの？\n男(おとこ)：最近(さいきん)の円高(えんだか)でABCカンパニーへの出荷数(しゅっかすう)がどれくらい落ち込ん(おちこん)でいるのか調(しら)べるようにって、課長(かちょう)に言(い)われましたので。\n女(おんな)：あー、それなら、北米支店(ほくべいしてん)の報告(ほうこく)を見(み)たほうが早(はや)いわね。\n男(おとこ)：はい、わかりました。ありがとうございます。\nナレーター：新入社員(しんにゅうしゃいん)は、どのファイルを見(み)ますか。",
    "translationZhTW": "旁白：新進員工向前輩詢問海外相關檔案。新進員工最後會看哪個檔案？\n男：前輩，我想看和美國ABC公司交易的資料，海外相關的架子上要看哪個檔案？\n女：那看出口實績或海外交易客戶名單應該就知道吧。不過你具體想查什麼？\n男：課長要我查最近日圓升值後，對ABC公司的出貨量下降了多少。\n女：啊，那看北美分公司的報告比較快。\n男：好，明白了，謝謝。\n旁白：新進員工會看哪個檔案？",
