    "id": "BJT_TRUE02_P2_S3_Q02",
    "transcript": "ナレーター：男の人が、お客と電話で話しています。男の人は、注文伝票のどこを変更しますか。\n男：はい、ヤマダ製作所です。\n女：田中屋ですが、いつもお世話になっております。\n男：あ、先日はご注文をいただき、ありがとうございました。\n女：その件でお電話したんですが、納期を1週間早めていただくことはできますか？\n男：はい、できると思いますが、ただ今確認いたしますので、しばらくお待ちいただけますでしょうか？\n女：ええ。あの、もし数量が足りないようでしたら、ある分だけでも先にいただきたいんですが。\n男：承知いたしました。少々お待ちください。……お待たせいたしました。在庫はございますので、至急手配いたします。\n女：すみません。よろしくお願いします。\nナレーター：男の人は、注文伝票のどこを変更しますか。",
    "transcriptWithFurigana": "ナレーター：男(おとこ)の人(ひと)が、お客(きゃく)と電話(でんわ)で話(はなし)しています。男(おとこ)の人(ひと)は、注文伝票(ちゅうもんでんぴょう)のどこを変更(へんこう)しますか。\n男(おとこ)：はい、ヤマダ製作所(せいさくしょ)です。\n女(おんな)：田中(たなか)屋(や)ですが、いつもお世(よ)話(はなし)になっております。\n男(おとこ)：あ、先日(せんじつ)はご注文(ちゅうもん)をいただき、ありがとうございました。\n女(おんな)：その件(けん)でお電話(でんわ)したんですが、納期(のうき)を1週間(しゅうかん)早(はや)めていただくことはできますか？\n男(おとこ)：はい、できると思(おも)いますが、ただ今(いま)確認(かくにん)いたしますので、しばらくお待(ま)ちいただけますでしょうか？\n女(おんな)：ええ。あの、もし数量(すうりょう)が足(た)りないようでしたら、ある分(ふん)だけでも先(さき)にいただきたいんですが。\n男(おとこ)：承知(しょうち)いたしました。少々(しょうしょう)お待(ま)ちください。……お待(ま)たせいたしました。在庫(ざいこ)はございますので、至急(しきゅう)手配(てはい)いたします。\n女(おんな)：すみません。よろしくお願(ねが)いします。\nナレーター：男(おとこ)の人(ひと)は、注文伝票(ちゅうもんでんぴょう)のどこを変更(へんこう)しますか。",
    "translationZhTW": "旁白：男子和顧客在電話中交談。男子會修改訂單傳票的哪一欄？\n男：您好，這裡是山田製作所。\n女：我是田中屋，承蒙照顧。\n男：前些日子感謝您的訂購。\n女：我是為那件事打來的，可以把交期提前一週嗎？\n男：應該可以，我現在確認，請稍等。\n女：好。如果數量不夠，有多少先給多少也可以。\n男：明白。……讓您久等了，庫存足夠，我們會立刻安排。\n女：麻煩您。\n旁白：男子會修改訂單傳票的哪一欄？",
