    "transcript": "ナレーター：食品会社の上司と部下が、展示会の準備について、話しています。部下は、まだ準備が終わっていないのは、どの項目だと言っていますか。\n女：展示会、いよいよ来月に迫ってきたわね。準備は順調？\n男：はい、こちらが作業一覧なんですが……。先週、招待状の発送作業を終えました。\n女：それなら一安心ね。イベント内容のほうは、どんな感じ？\n男：はい。今回のイベントは、試食してもらうだけじゃなくて、実際にうちの商品を使った、簡単な料理を作るデモンストレーションを取り入れようと考えています。\n女：へえ、面白そう。\n男：ラッキーなことに、ちょうど隣のブースが、厨房設備機器を専門にしている会社で、そちらから、器具も講師もお借りする手はずが整ったんですよ。\n女：へえ、それはいいわね。単独でやるより、集客力も増すんじゃない？\n男：はい、だから、ブースに大勢のお客さんが集まっても見やすいように、全体の配置をどうするか、苦労しているんです。いずれにしても、必ず成功させます。\n女：頼もしいわね。期待してるわ。\nナレーター：部下は、まだ準備が終わっていないのは、どの項目だと言っていますか。",
    "transcriptWithFurigana": "ナレーター：食品会社(しょくひんがいしゃ)の上司(じょうし)と部下(ぶか)が、展示会(てんじかい)の準備(じゅんび)について、話(はなし)しています。部下(ぶか)は、まだ準備(じゅんび)が終(お)わっていないのは、どの項目(こうもく)だと言(い)っていますか。\n女(おんな)：展示会(てんじかい)、いよいよ来月(らいげつ)に迫って(せまって)きたわね。準備(じゅんび)は順調(じゅんちょう)？\n男(おとこ)：はい、こちらが作業一覧(さぎょういちらん)なんですが……。先週(せんしゅう)、招待状(しょうたいじょう)の発送作業(はっそうさぎょう)を終(お)えました。\n女(おんな)：それなら一安心(あんしん)ね。イベント内容(ないよう)のほうは、どんな感(かん)じ？\n男(おとこ)：はい。今回(こんかい)のイベントは、試食(ししょく)してもらうだけじゃなくて、実際(じっさい)にうちの商品(しょうひん)を使(つか)った、簡単(かんたん)な料理(りょうり)を作(つく)るデモンストレーションを取(と)り入(い)れようと考(かんが)えています。\n女(おんな)：へえ、面白(おもしろ)そう。\n男(おとこ)：ラッキーなことに、ちょうど隣(となり)のブースが、厨房設備機器(ちゅうぼうせつびきき)を専門(せんもん)にしている会社(かいしゃ)で、そちらから、器具(きぐ)も講師(こうし)もお借(か)りする手(て)はずが整った(ととのった)んですよ。\n女(おんな)：へえ、それはいいわね。単独(たんどく)でやるより、集客力(しゅうきゃくりょく)も増(ふ)すんじゃない？\n男(おとこ)：はい、だから、ブースに大勢(おおぜい)のお客(きゃく)さんが集(あつ)まっても見(み)やすいように、全体(ぜんたい)の配置(はいち)をどうするか、苦労(くろう)しているんです。いずれにしても、必(かなら)ず成功(せいこう)させます。\n女(おんな)：頼(たの)もしいわね。期待(きたい)してるわ。\nナレーター：部下(ぶか)は、まだ準備(じゅんび)が終(お)わっていないのは、どの項目(こうもく)だと言(い)っていますか。",
    "translationZhTW": "旁白：食品公司的上司與部下正在談展示會準備。部下說哪個項目還沒準備完成？\n女：展示會下個月就到了，準備順利嗎？\n男：是，這是工作清單。上週已完成邀請函寄送。\n女：那就放心了。活動內容呢？\n男：這次不只試吃，也打算加入用本公司商品做簡單料理的示範。\n女：聽起來很有趣。\n男：很幸運，隔壁攤位正好是廚房設備公司，器材和講師都已經談妥借用。\n女：那很好，應該比單獨辦更能吸引人。\n男：是。所以為了讓攤位即使聚集很多客人也看得清楚，我正在苦惱整體配置要怎麼安排。不管怎樣，我一定會讓活動成功。\n女：很可靠，期待你的表現。\n旁白：部下說哪個項目還沒準備完成？",
