    "transcript": "ナレーター：男の人が、電話で、会社の場所を聞いています。会社はどこにありますか。\n女：はい。立山工業の山本でございます。\n男：あ、私、大山産業の高橋と申します。\n女：大山産業の高橋様でいらっしゃいますね。いつもお世話になっております。\n男：こちらこそ、お世話になっております。実は、今からそちらに伺いたいと思うのですが、場所がわからなくて……。どうやって行けばいいのかお尋ねしたいのですが。今、南町駅なんですが。\n女：それでは、駅の南口を出てください。\n男：はい。南口ですね。\n女：そこから、東和タワーを背にして、まっすぐ歩いていただけますか。\n男：東和タワーを後ろにまっすぐですね。\n女：はい。そして二つ目の信号を右に曲がっていただいて、一つ目の角に公園があるかと思います。その前のビルの3階です。\n男：一つ目の角を曲がるんですか？\n女：いいえ、二つ目の信号です。\n男：わかりました。\nナレーター：会社はどこにありますか。",
    "transcriptWithFurigana": "ナレーター：男(おとこ)の人(ひと)が、電話(でんわ)で、会社(かいしゃ)の場所(ばしょ)を聞(き)いています。会社(かいしゃ)はどこにありますか。\n女(おんな)：はい。立山工業(たてやまこうぎょう)の山本(やまもと)でございます。\n男(おとこ)：あ、私(わたし)、大山産業(おおやまさんぎょう)の高橋(たかはし)と申します(もうします)。\n女(おんな)：大山産業(おおやまさんぎょう)の高橋(たかはし)様(さま)でいらっしゃいますね。いつもお世(よ)話(はなし)になっております。\n男(おとこ)：こちらこそ、お世(よ)話(はなし)になっております。実は(じつは)、今(いま)からそちらに伺(うかが)いたいと思(おも)うのですが、場所(ばしょ)がわからなくて……。どうやって行(い)けばいいのかお尋(たず)ねしたいのですが。今(いま)、南町駅(みなみちょうえき)なんですが。\n女(おんな)：それでは、駅(えき)の南口(みなみぐち)を出(で)てください。\n男(おとこ)：はい。南口(みなみぐち)ですね。\n女(おんな)：そこから、東和タワー(とうわたわー)を背に(せに)して、まっすぐ歩(ある)いていただけますか。\n男(おとこ)：東和タワー(とうわたわー)を後(あと)ろにまっすぐですね。\n女(おんな)：はい。そして二つ目(ふたつめ)の信号(しんごう)を右(みぎ)に曲がって(まがって)いただいて、一つ目(ひとつめ)の角(かど)に公園(こうえん)があるかと思(おも)います。その前(まえ)のビルの3階(かい)です。\n男(おとこ)：一つ目(ひとつめ)の角(かど)を曲(ま)がるんですか？\n女(おんな)：いいえ、二つ目(ふたつめ)の信号(しんごう)です。\n男(おとこ)：わかりました。\nナレーター：会社(かいしゃ)はどこにありますか。",
    "translationZhTW": "旁白：男子在電話中詢問公司位置。公司在哪裡？\n女：您好，立山工業，我是山本。\n男：我是大山產業的高橋。\n女：大山產業高橋先生，承蒙照顧。\n男：我現在想去貴公司，但不知道位置，想請教怎麼走。我現在在南町站。\n女：請從車站南口出去。\n男：南口。\n女：背對東和大樓直走。\n男：背對東和大樓直走。\n女：是，然後在第二個紅綠燈右轉，第一個街角應該有公園，我們在公園前那棟大樓三樓。\n男：是在第一個街角轉彎嗎？\n女：不是，是第二個紅綠燈。\n男：明白了。\n旁白：公司在哪裡？",
