    "transcript": "ナレーター：上司と部下が、スケジュールの変更について、話しています。上司は、どの時間帯に追加したスケジュールを入れますか。\n男：佐藤部長、ちょっとよろしいですか？\n女：ええ、なに？\n男：例の共同開発の件で、AB産業の常務が、会って詳しい話を聞きたいとおっしゃっているんですが。\n女：いつがいいって？\n男：できたら来週の月曜日にお願いしたいと。時間はいつでもいいそうです。\n女：そう。ちょっと待って。ええと、月曜のスケジュールは……。あ、結構入ってるわねえ。午前中の会議は大事な案件があるから、抜けるわけにはいかないし。大阪行きを遅らせようか。\n男：この東西自動車さんとの商談は早めに切り上げられそうなんですか？\n女：うーん、これもわりと面倒なのよね。\n男：では、企画とのミーティングを前に持っていくわけには……。\n女：うん。仕方ない。そっちは1時間もかからない予定だから、朝一番にしてもらえば2時間くらい空くから、ここにAB産業を入れましょう。\n男：はい、わかりました。\nナレーター：上司は、どの時間帯に追加したスケジュールを入れますか。",
    "transcriptWithFurigana": "ナレーター：上司(じょうし)と部下(ぶか)が、スケジュールの変更(へんこう)について、話(はなし)しています。上司(じょうし)は、どの時間帯(じかんたい)に追加(ついか)したスケジュールを入(い)れますか。\n男(おとこ)：佐藤(さとう)部長(ぶちょう)、ちょっとよろしいですか？\n女(おんな)：ええ、なに？\n男(おとこ)：例(たと)の共同開発(きょうどうかいはつ)の件(けん)で、AB産業(さんぎょう)の常務(じょうむ)が、会(あ)って詳(くわ)しい話(はなし)を聞(き)きたいとおっしゃっているんですが。\n女(おんな)：いつがいいって？\n男(おとこ)：できたら来週(らいしゅう)の月曜日(げつようび)にお願(ねが)いしたいと。時間(じかん)はいつでもいいそうです。\n女(おんな)：そう。ちょっと待(ま)って。ええと、月曜(げつよう)のスケジュールは……。あ、結構(けっこう)入(い)ってるわねえ。午前中(ごぜんちゅう)の会議(かいぎ)は大事(だいじ)な案件(あんけん)があるから、抜(ぬ)けるわけにはいかないし。大阪(おおさか)行(い)きを遅(おく)らせようか。\n男(おとこ)：この東西自動車(とうざいじどうしゃ)さんとの商談(しょうだん)は早(はや)めに切(き)り上(うえ)げられそうなんですか？\n女(おんな)：うーん、これもわりと面倒(めんどう)なのよね。\n男(おとこ)：では、企画(きかく)とのミーティングを前(まえ)に持(も)っていくわけには……。\n女(おんな)：うん。仕方(しかた)ない。そっちは1時間(じかん)もかからない予定(よてい)だから、朝一番(あさいちばん)にしてもらえば2時間(じかん)くらい空く(あく)から、ここにAB産業(さんぎょう)を入(い)れましょう。\n男(おとこ)：はい、わかりました。\nナレーター：上司(じょうし)は、どの時間帯(じかんたい)に追加(ついか)したスケジュールを入(い)れますか。",
    "translationZhTW": "旁白：上司與部下在談行程更動。上司會把新增行程排在哪個時段？\n男：佐藤部長，可以打擾一下嗎？\n女：可以，什麼事？\n男：關於那個共同開發案，AB產業的常務想見面詳細了解。\n女：希望什麼時候？\n男：如果可以，希望下週一。時間都可以。\n女：我看看週一行程……排得很滿。上午會議有重要案件，不能離席；要不要把大阪行程延後？\n男：和東西汽車的商談能提早結束嗎？\n女：這個也挺麻煩。\n男：那企劃部會議能不能提前？\n女：嗯，只好這樣。那個預計不到一小時，如果排在一早，就能空出約兩小時，把AB產業排在這裡。\n男：明白。\n旁白：新增行程會排在哪個時段？",
