    "transcript": "ナレーター：上司と部下が、セミナーの広告案について、話しています。部下は、このあと、広告案のどこを直しますか。\n女：課長、今度のセミナーの広告なんですが、ちょっと見ていただけないでしょうか？\n男：ああ、それね。「事例から学ぶ」っていう言葉を入れたんだね。うん、なかなかいいじゃない。\n女：ありがとうございます。\n男：ただ、タイトルのフォント、小さいね。大きくして、もう少し見やすくできない？\n女：あ、でもこれ以上大きくすると、1行におさまらないんですよ。\n男：じゃあ、仕方ないね。……あれ？これ、講師の氏名、漢字が間違ってるじゃない。ほら、ここ。\n女：あ、本当ですね。すみません。\n男：それから、主催だけど、こんなところに入れたら変だよ。普通は一番下かな。\n女：わかりました。\n男：FAXの番号とメールアドレス、間違ってないよね？\n女：はい。\n男：じゃ、それでよろしく。\nナレーター：部下は、このあと、広告案のどこを直しますか。",
    "transcriptWithFurigana": "ナレーター：上司(じょうし)と部下(ぶか)が、セミナーの広告案(こうこくあん)について、話(はなし)しています。部下(ぶか)は、このあと、広告案(こうこくあん)のどこを直(なお)しますか。\n女(おんな)：課長(かちょう)、今度(こんど)のセミナーの広告(こうこく)なんですが、ちょっと見(み)ていただけないでしょうか？\n男(おとこ)：ああ、それね。「事例(じれい)から学(まな)ぶ」っていう言葉(ことば)を入(い)れたんだね。うん、なかなかいいじゃない。\n女(おんな)：ありがとうございます。\n男(おとこ)：ただ、タイトルのフォント、小さい(ちいさい)ね。大きくして、もう少(すこ)し見(み)やすくできない？\n女(おんな)：あ、でもこれ以上(うえ)大きくすると、1行(い)におさまらないんですよ。\n男(おとこ)：じゃあ、仕方(しかた)ないね。……あれ？これ、講師(こうし)の氏名(しめい)、漢字(かんじ)が間違(まちが)ってるじゃない。ほら、ここ。\n女(おんな)：あ、本当(ほんとう)ですね。すみません。\n男(おとこ)：それから、主催(しゅさい)だけど、こんなところに入(い)れたら変(か)だよ。普通(ふつう)は一番下(いちばんした)かな。\n女(おんな)：わかりました。\n男(おとこ)：FAXの番号(ばんごう)とメールアドレス、間違(まちが)ってないよね？\n女(おんな)：はい。\n男(おとこ)：じゃ、それでよろしく。\nナレーター：部下(ぶか)は、このあと、広告案(こうこくあん)のどこを直(なお)しますか。",
    "translationZhTW": "旁白：上司與部下在談研討會廣告稿。部下接下來要修改哪裡？\n女：課長，可以幫我看一下這次研討會的廣告嗎？\n男：好。「從案例學習」這句加進去了，不錯。\n女：謝謝。\n男：不過標題字體太小，可以放大、看清楚一點嗎？\n女：再大就放不進一行了。\n男：那就沒辦法。咦？講師姓名的漢字寫錯了，在這裡。\n女：真的，抱歉。\n男：另外，「主辦單位」放這裡很奇怪，通常應放最下方。\n女：明白。\n男：傳真號碼和電子郵件沒錯吧？\n女：是。\n男：那就麻煩了。\n旁白：部下接下來要修改廣告稿的哪裡？",
